def transform(grid):
    # Rows consist of a solid color bar on a uniform background; extend the
    # bar's endpoint through the remainder of that row in color 1.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        colors = [v for v in row if v != row[0]]
        if colors:
            bar_color = colors[0]
            positions = [c for c, v in enumerate(row) if v == bar_color]
            if positions:
                last = max(positions)
                for c in range(last + 1, len(row)):
                    out[r][c] = 1
    return out

